/**
 * Demo drawing: LOX / liquid methane feed and pressurization of a propulsion
 * test stand, on one A1 sheet. It exists to show a realistically dense P&ID
 * drawn only with the built-in library, and is seeded into the demo project
 * (`backend/app/demo/test_stand_pid.json`, regenerated by the test next to
 * this file with UPDATE_DEMO_PID=1).
 *
 * The sheet is laid out by a small builder: `chain` walks a pipe run in one
 * direction, placing inline symbols port to port, so every connection is exact
 * by construction rather than by hand-typed coordinates.
 */
import { SymbolRegistry } from "../library";
import { createEmptyDocument, type Item, type LineItem, type LineType, type Point, type Rotation, type SchematicDocument, type SymbolItem } from "../types";

export type Dir = "E" | "S" | "W" | "N";

export const VEC: Record<Dir, Point> = { E: { x: 1, y: 0 }, S: { x: 0, y: 1 }, W: { x: -1, y: 0 }, N: { x: 0, y: -1 } };
/** How an inline symbol is turned so its `in` port faces back along the run. */
export const ORIENT: Record<Dir, { rotation: Rotation; mirror?: boolean }> = {
  E: { rotation: 0 },
  S: { rotation: 90 },
  // Mirrored rather than rotated, so actuators stay above the line.
  W: { rotation: 0, mirror: true },
  N: { rotation: 270 }
};

export type LineData = { number: string; service: string; size: string; lineClass: string; designPressure?: string };

export type SymbolSpec = {
  key: string;
  tag?: string;
  /** Free caption for items that carry no tag (terminators). */
  label?: string;
  /** Turn the symbol end for end, so an actuator sits on the other side of the line. */
  flip?: boolean;
  actuator?: string;
  /** Catalog part number assigned by the seed. */
  part?: string;
  /** Entry and exit ports for symbols that are not plain in/out. */
  from?: string;
  to?: string;
  /** Pair id of an off-page connector (`fields.ref`). */
  ref?: string;
};

export type Step =
  | number
  | { run: number; label: true }
  | { mark: string }
  | { turn: Dir }
  /** Run on until the cursor reaches this x (or y, for a vertical run). */
  | { until: number }
  | { data: LineData }
  | SymbolSpec;

export type DemoDrawing = {
  number: string;
  title: string;
  size: "A1";
  system: { name: string; fluid: string };
  notes: string[];
  lineClasses: Array<{ name: string; description: string; material: string; rating: string; wall: string; sizes: string[] }>;
  /** Catalog part number per document item id. */
  parts: Record<string, string>;
  document: SchematicDocument;
};

export class Builder {
  readonly registry = SymbolRegistry.withBuiltins();
  readonly items: Item[] = [];
  readonly marks: Record<string, Point> = {};
  readonly parts: Record<string, string> = {};
  private readonly ids = new Map<string, number>();

  /** `scope` prefixes generated ids, so the sheets of one drawing do not share any. */
  constructor(private readonly scope = "") {}

  private id(prefix: string): string {
    const next = (this.ids.get(prefix) ?? 0) + 1;
    this.ids.set(prefix, next);
    return `${this.scope}${prefix}-${next}`;
  }

  /** Place a symbol so that one of its ports lands on `at`; returns its ports in sheet coordinates. */
  place(spec: SymbolSpec, portId: string, at: Point, orient: { rotation: Rotation; mirror?: boolean; scale?: number } = { rotation: 0 }): Record<string, Point> {
    const item: SymbolItem = {
      id: spec.tag ? spec.tag.toLowerCase() : this.id(spec.key.replaceAll("_", "-")),
      kind: "symbol",
      layer: "symbols",
      symbol: { library: "fsdp", key: spec.key, version: 1 },
      position: { x: 0, y: 0 },
      rotation: orient.rotation,
      ...(orient.mirror ? { mirror: true } : {}),
      ...(orient.scale ? { scale: orient.scale } : {}),
      ...(spec.tag ? { tag: spec.tag } : {}),
      ...(spec.label ? { label: spec.label } : {}),
      ...(spec.actuator ? { actuator: { library: "fsdp", key: spec.actuator, version: 1 } } : {}),
      fields: spec.ref ? { ref: spec.ref } : {}
    };
    const port = this.registry.portsOf(item).find((entry) => entry.id === portId);
    if (!port) throw new Error(`${spec.key} has no port ${portId}`);
    item.position = { x: at.x - port.position.x, y: at.y - port.position.y };
    this.items.push(item);
    if (spec.part) this.parts[item.id] = spec.part;
    return Object.fromEntries(this.registry.portsOf(item).map((entry) => [entry.id, entry.position]));
  }

  line(points: Point[], data?: LineData, options: { label?: boolean; lineType?: LineType; thin?: boolean; arrow?: boolean } = {}): void {
    const lineType = options.lineType ?? "process";
    const length = points.slice(1).reduce((sum, point, index) => sum + Math.abs(point.x - points[index].x) + Math.abs(point.y - points[index].y), 0);
    const item: LineItem = {
      id: this.id(lineType === "process" ? "ln" : "sig"),
      kind: "line",
      layer: lineType === "process" ? "process" : "signal",
      points,
      lineType,
      ...(options.thin ? { strokeWidth: 0.25 } : {}),
      ...(options.arrow ? { showArrow: true } : {}),
      ...(data
        ? {
            lineNumber: data.number,
            service: data.service,
            size: data.size,
            lineClass: data.lineClass,
            ...(data.designPressure ? { designPressure: data.designPressure } : {}),
            showNumberLabel: Boolean(options.label),
            showSpecLabel: Boolean(options.label),
            ...(options.label && length >= 30 ? { annotations: [{ id: "flow", kind: "flow_arrow" as const, at: 1 - 4 / length }] } : {})
          }
        : {}),
      fields: {}
    };
    this.items.push(item);
  }

  /** Walk a pipe run from `start`: numbers are pipe lengths in mm, symbols are placed port to port. */
  chain(start: Point, direction: Dir, data: LineData, steps: Step[]): Point {
    let dir = direction;
    let current = data;
    let cursor = { ...start };
    let points: Point[] = [cursor];
    let labelled = false;
    const flush = () => {
      if (points.length > 1) this.line(points, current, { label: labelled });
      points = [cursor];
      labelled = false;
    };
    const advance = (length: number) => {
      cursor = { x: cursor.x + VEC[dir].x * length, y: cursor.y + VEC[dir].y * length };
      // Extend a straight segment instead of adding a collinear vertex.
      if (points.length > 1) {
        const previous = points[points.length - 2];
        const last = points[points.length - 1];
        if ((previous.x === last.x && last.x === cursor.x) || (previous.y === last.y && last.y === cursor.y)) points.pop();
      }
      points.push(cursor);
    };
    for (const step of steps) {
      if (typeof step === "number") advance(step);
      else if ("run" in step) {
        // Its own piece, so the number is centred on this clear stretch and not on a tee.
        flush();
        advance(step.run);
        labelled = true;
        flush();
      } else if ("mark" in step) this.marks[step.mark] = cursor;
      else if ("turn" in step) dir = step.turn;
      else if ("until" in step) {
        const distance = VEC[dir].x ? (step.until - cursor.x) * VEC[dir].x : (step.until - cursor.y) * VEC[dir].y;
        if (distance <= 0) throw new Error(`Run ${current.number} is already past ${step.until}`);
        advance(distance);
      }
      else if ("data" in step) {
        flush();
        current = step.data;
      } else {
        flush();
        const opposite: Record<Dir, Dir> = { E: "W", W: "E", N: "S", S: "N" };
        const ports = step.flip
          ? this.place(step, step.to ?? "out", cursor, ORIENT[opposite[dir]])
          : this.place(step, step.from ?? "in", cursor, ORIENT[dir]);
        cursor = ports[step.flip ? (step.from ?? "in") : (step.to ?? "out")];
        points = [cursor];
      }
    }
    flush();
    return cursor;
  }

  /** Instrument bubble on a short tap off `at`, on the given side of the line. */
  bubble(at: Point, side: Dir, tag: string, options: { key?: string; stem?: number; part?: string } = {}): Record<string, Point> {
    const stem = options.stem ?? 10;
    const end = { x: at.x + VEC[side].x * stem, y: at.y + VEC[side].y * stem };
    this.line([at, end], undefined, { thin: true });
    // The process port is at the bottom of the bubble; turn it to face the tap.
    const rotation: Record<Dir, Rotation> = { N: 0, E: 90, S: 180, W: 270 };
    return this.place({ key: options.key ?? "instrument", tag, part: options.part }, "process", end, { rotation: rotation[side] });
  }

  signal(points: Point[], lineType: LineType = "signal_electric"): void {
    this.line(points, undefined, { lineType });
  }

  label(text: string, at: Point, options: { size?: number; anchor?: "start" | "middle" | "end" } = {}): void {
    this.items.push({ id: this.id("txt"), kind: "label", layer: "annotation", position: at, text, fontSize: options.size ?? 3.5, rotation: 0, anchor: options.anchor ?? "start" });
  }
}

export const at = (x: number, y: number): Point => ({ x, y });

const HP: LineData = { number: "GHE-101", service: "GHe", size: '1/2"', lineClass: "HP-316", designPressure: "400 bar" };
const HEADER: LineData = { number: "GHE-102", service: "GHe", size: '1/2"', lineClass: "MP-316", designPressure: "60 bar" };
const PURGE_HP: LineData = { number: "GN2-151", service: "GN2", size: '1/2"', lineClass: "HP-316", designPressure: "200 bar" };
const PURGE: LineData = { number: "GN2-152", service: "GN2", size: '1/2"', lineClass: "MP-316", designPressure: "60 bar" };

type Side = {
  /** 1 for the LOX side (tank left of the engine), -1 for the methane side. */
  sign: 1 | -1;
  fluid: string;
  prefix: string;
  /** Hundreds digit of the tags on this side. */
  series: number;
  tankX: number;
  tankName: string;
  engineNozzle: Point;
};

const HEADER_Y = 70;
const PURGE_Y = 530;

/** Relief valve on a short tap off `tee`, discharging upward through a vent. */
function reliefTap(b: Builder, tee: Point, away: Dir, data: LineData, tag: string, ventTag: string, key = "relief_valve"): void {
  const inlet = at(tee.x + VEC[away].x * 10, tee.y);
  b.line([tee, inlet], data);
  // Inlet facing the tap, outlet up.
  const relief = b.place({ key, tag, part: "AMPH-RV-001" }, "in", inlet, away === "E" ? { rotation: 0 } : { rotation: 0, mirror: true });
  b.chain(relief.vent, "N", { ...data, number: `${data.number}V` }, [5, { turn: away }, 5, { key: "vent_atmosphere", tag: ventTag }]);
}

/** One propellant side: pressurization branch, tank with fill, vent and relief, and the feed line to the engine. */
function propellantSide(b: Builder, side: Side): { mainValve: Point } {
  const { sign, fluid, prefix, series, tankX } = side;
  const out: Dir = sign === 1 ? "E" : "W";
  const back: Dir = sign === 1 ? "W" : "E";
  const n = (offset: number) => String(series * 100 + offset);
  const cryo = (number: string, size: string): LineData => ({ number: `${prefix}-${number}`, service: fluid, size, lineClass: "CRYO-304L", designPressure: "40 bar" });
  const press: LineData = { number: `GHE-${n(11)}`, service: "GHe", size: '1/2"', lineClass: "MP-316", designPressure: "60 bar" };
  const ullage: LineData = { number: `GHE-${n(12)}`, service: "GHe", size: '1"', lineClass: "CRYO-304L", designPressure: "40 bar" };
  const feed = cryo(n(41), '2"');

  // Pressurization branch off the regulated helium header, down into the tank ullage.
  const top = b.chain(at(tankX, HEADER_Y), "S", press, [
    10,
    { key: "solenoid_valve", tag: `SV-${n(11)}`, part: "AMPH-SV-001", flip: sign === -1 },
    10,
    { key: "orifice", tag: `RO-${n(11)}` },
    { run: 30, label: true },
    { key: "check_valve", tag: `CV-${n(11)}` },
    { data: ullage },
    10,
    { mark: "ullage" },
    15
  ]);
  const tank = b.place({ key: "tank", tag: `TK-${n(1)}` }, "top", top, { rotation: 0, scale: 4 });
  b.label(side.tankName, at(tankX, top.y + 34), { size: 3.5, anchor: "middle" });
  b.label("1.5 m³  ·  MAWP 40 bar", at(tankX, top.y + 40), { size: 2.5, anchor: "middle" });

  // Vent and relief off the ullage line, away from the engine.
  b.chain(b.marks.ullage, back, ullage, [
    15,
    { mark: "pt" },
    15,
    { mark: "relief" },
    { run: 35, label: true },
    { key: "pneumatic_valve", tag: `PV-${n(31)}` },
    { data: cryo(n(32), '1"') },
    15,
    { key: "silencer", tag: `SIL-${n(31)}` },
    10,
    { key: "vent_atmosphere", tag: `VENT-${n(31)}` }
  ]);
  b.bubble(b.marks.pt, "N", `PT-${n(21)}`, { part: "AMPH-PT-001" });
  // Tank relief: inlet below, discharge pointing away from the tank.
  const reliefIn = at(b.marks.relief.x, b.marks.relief.y - 10);
  b.line([b.marks.relief, reliefIn], ullage);
  const relief = b.place({ key: "safety_valve", tag: `PSV-${n(31)}`, part: "AMPH-RV-001" }, "in", reliefIn, sign === 1 ? { rotation: 270 } : { rotation: 90, mirror: true });
  b.chain(relief.vent, back, cryo(n(33), '1"'), [15, { key: "vent_atmosphere", tag: `VENT-${n(32)}` }]);

  // Level and temperature on the tank shell (the side facing the engine), sharing one nozzle.
  const shell = sign === 1 ? tank.out : tank.left;
  const tap = at(shell.x + sign * 7.5, shell.y);
  b.line([shell, tap], undefined, { thin: true });
  b.bubble(tap, out, `LT-${n(21)}`, { stem: 7.5 });
  b.line([tap, at(tap.x, tap.y + 15)], undefined, { thin: true });
  b.bubble(at(tap.x, tap.y + 15), out, `TE-${n(21)}`, { stem: 7.5 });

  // Fill line from the ground supply into the far side of the tank.
  const fillNozzle = sign === 1 ? tank.left : tank.out;
  const fill = cryo(n(21), '1"');
  const supply = b.place({ key: "terminator_in", label: `${fluid} FILL` }, "out", at(fillNozzle.x - sign * 130, fillNozzle.y), sign === 1 ? { rotation: 0 } : { rotation: 0, mirror: true });
  b.chain(supply.out, out, fill, [
    7.5,
    { key: "quick_disconnect", tag: `QD-${n(21)}` },
    10,
    { key: "ball_valve", tag: `HV-${n(21)}`, actuator: "act_lever" },
    10,
    { mark: "fillRelief" },
    { run: 32.5, label: true },
    { key: "check_valve", tag: `CV-${n(21)}` },
    { until: fillNozzle.x }
  ]);
  // Thermal relief for liquid trapped between the fill valve and the check valve.
  const fillTrv = at(b.marks.fillRelief.x, b.marks.fillRelief.y + 10);
  b.line([b.marks.fillRelief, fillTrv], fill);
  const fillRelief = b.place({ key: "relief_valve", tag: `TRV-${n(22)}`, part: "AMPH-RV-001" }, "in", fillTrv, sign === 1 ? { rotation: 90 } : { rotation: 270, mirror: true });
  b.chain(fillRelief.vent, out, cryo(n(23), '1/2"'), [10, { key: "vent_atmosphere", tag: `VENT-${n(22)}` }]);

  // Feed line: out of the tank bottom, through the main valve and metering, across to the engine.
  b.chain(tank.bottom, "S", feed, [
    10,
    { mark: "drain" },
    10,
    { key: "ball_valve", tag: `XV-${n(41)}`, actuator: "act_piston", flip: sign === -1 },
    10,
    { mark: "feedRelief" },
    10,
    { key: "strainer", tag: `STR-${n(41)}` },
    { run: 30, label: true },
    { key: "turbine_meter", tag: `FE-${n(41)}` },
    10,
    { mark: "feedPt" },
    12.5,
    { mark: "feedTe" },
    { until: side.engineNozzle.y },
    { turn: out },
    15,
    { mark: "purge" },
    15,
    { key: "check_valve", tag: `CV-${n(42)}` },
    10,
    { mark: "inletPt" },
    12.5,
    { mark: "inletTe" },
    { until: side.engineNozzle.x - sign * 20 },
    { mark: "bleed" },
    { until: side.engineNozzle.x }
  ]);
  const purgeTee = b.marks.purge;
  b.bubble(b.marks.feedPt, out, `PT-${n(41)}`, { part: "AMPH-PT-001" });
  b.bubble(b.marks.feedTe, out, `TE-${n(41)}`);
  b.bubble(b.marks.inletPt, "N", `PT-${n(42)}`, { part: "AMPH-PT-001" });
  b.bubble(b.marks.inletTe, "N", `TE-${n(42)}`);
  // Thermal relief for liquid trapped between the main valve and the inlet check valve.
  reliefTap(b, b.marks.feedRelief, back, feed, `TRV-${n(42)}`, `VENT-${n(42)}`);

  // Tank drain.
  b.chain(b.marks.drain, back, feed, [15, { key: "ball_valve", tag: `HV-${n(42)}`, actuator: "act_lever" }, { data: cryo(n(43), '1"') }, 10, { key: "drain", tag: `DRN-${n(41)}` }]);

  // Chill-down bleed at the engine inlet, to the vent stack.
  b.chain(b.marks.bleed, "S", feed, [
    10,
    { key: "globe_valve", tag: `XV-${n(61)}`, actuator: "act_diaphragm", flip: sign === 1 },
    { data: cryo(n(61), '1"') },
    10,
    { turn: back },
    10,
    { key: "terminator", label: "VENT STACK", from: "in", to: "in" }
  ]);

  // Purge into the feed line, upstream of the engine inlet check valve.
  b.chain(at(purgeTee.x, PURGE_Y), "N", PURGE, [
    10,
    { key: "solenoid_valve", tag: `SV-${n(52)}`, part: "AMPH-SV-001", flip: sign === 1 },
    { data: feed },
    10,
    { key: "check_valve", tag: `CV-${n(53)}` },
    { until: purgeTee.y }
  ]);

  const mainValve = b.registry.portsOf(b.items.find((item) => item.id === `xv-${n(41)}`) as SymbolItem).find((port) => port.id === "signal")!.position;
  return { mainValve };
}

export function buildTestStandDemo(): DemoDrawing {
  const b = new Builder();
  const lox: Side = { sign: 1, fluid: "LOX", prefix: "LOX", series: 1, tankX: 330, tankName: "LOX RUN TANK", engineNozzle: at(430, 455) };
  const ch4: Side = { sign: -1, fluid: "LCH4", prefix: "CH4", series: 2, tankX: 590, tankName: "LCH4 RUN TANK", engineNozzle: at(490, 455) };

  // Helium supply: tube trailer connection, filtration, and regulation down to the tank header.
  const supply = b.place({ key: "terminator_in", label: "GHe SUPPLY" }, "out", at(45, HEADER_Y));
  b.chain(supply.out, "E", HP, [
    10,
    { key: "ball_valve", tag: "HV-001", actuator: "act_lever" },
    10,
    { key: "filter", tag: "F-001", part: "AMPH-FL-001" },
    15,
    { mark: "pt1" },
    { run: 35, label: true },
    { key: "dome_loaded_regulator", tag: "PCV-001", part: "AMPH-PR-001" },
    { data: HEADER },
    15,
    { mark: "pt2" },
    15,
    { key: "check_valve", tag: "CV-001" },
    15,
    { mark: "relief" },
    { run: 45, label: true },
    { until: ch4.tankX }
  ]);
  b.bubble(b.marks.pt1, "N", "PT-001", { part: "AMPH-PT-001" });
  const pt2 = b.bubble(b.marks.pt2, "N", "PT-002", { part: "AMPH-PT-001" });
  // Header relief, below the line, discharging to a vent.
  const reliefIn = at(b.marks.relief.x, b.marks.relief.y + 10);
  b.line([b.marks.relief, reliefIn], HEADER);
  const relief = b.place({ key: "relief_valve", tag: "PSV-001", part: "AMPH-RV-001" }, "in", reliefIn, { rotation: 90 });
  b.chain(relief.vent, "E", { ...HEADER, number: "GHE-103" }, [10, { key: "vent_atmosphere", tag: "VENT-001" }]);

  // Pressure control loop: PT-002 -> PIC-001 -> dome of PCV-001.
  const dome = b.registry.portsOf(b.items.find((item) => item.id === "pcv-001") as SymbolItem).find((port) => port.id === "dome")!.position;
  const pic = b.place({ key: "instrument_dcs", tag: "PIC-001" }, "process", at(dome.x, dome.y - 12.5));
  b.signal([dome, at(dome.x, dome.y - 12.5)], "signal_pneumatic");
  b.signal([pt2.signal_top, at(pt2.signal_top.x, pic.signal_right.y), pic.signal_right]);

  const loxSide = propellantSide(b, lox);
  const ch4Side = propellantSide(b, ch4);

  // Test article: both feed lines end on its inlet nozzles.
  b.items.push({
    id: "e-001",
    kind: "equipment",
    layer: "equipment",
    position: at(lox.engineNozzle.x, lox.engineNozzle.y - 25),
    size: { width: ch4.engineNozzle.x - lox.engineNozzle.x, height: 50 },
    tag: "E-001",
    name: "ENGINE (TEST ARTICLE)",
    boundary: "dashed",
    nozzles: [
      { id: "lox", x: 0, y: 25, side: "left", size: '2"' },
      { id: "ch4", x: ch4.engineNozzle.x - lox.engineNozzle.x, y: 25, side: "right", size: '2"' }
    ],
    fields: {}
  });

  // Emergency shutdown: one interlock closes both main propellant valves.
  const centreX = (lox.engineNozzle.x + ch4.engineNozzle.x) / 2;
  const esd = b.place({ key: "instrument_interlock", tag: "I-001" }, "signal_top", at(centreX, loxSide.mainValve.y - 5));
  b.signal([loxSide.mainValve, at(loxSide.mainValve.x, esd.signal_left.y), esd.signal_left]);
  b.signal([ch4Side.mainValve, at(ch4Side.mainValve.x, esd.signal_right.y), esd.signal_right]);
  b.label("ESD", at(centreX, esd.signal_top.y - 2), { size: 2.5, anchor: "middle" });

  // Nitrogen purge: regulated header along the bottom with a branch to each feed line.
  const purge = b.place({ key: "terminator_in", label: "GN2 SUPPLY" }, "out", at(45, PURGE_Y));
  b.chain(purge.out, "E", PURGE_HP, [
    10,
    { key: "ball_valve", tag: "HV-051", actuator: "act_lever" },
    10,
    { key: "filter", tag: "F-051", part: "AMPH-FL-001" },
    { run: 35, label: true },
    { key: "regulator", tag: "PCV-051", part: "AMPH-PR-001" },
    { data: PURGE },
    15,
    { mark: "purgePt" },
    15,
    { mark: "purgeRelief" },
    { run: 60, label: true },
    { until: ch4.tankX - 15 }
  ]);
  b.bubble(b.marks.purgePt, "N", "PT-051", { part: "AMPH-PT-001" });
  const purgeReliefIn = at(b.marks.purgeRelief.x, b.marks.purgeRelief.y + 10);
  b.line([b.marks.purgeRelief, purgeReliefIn], PURGE);
  const purgeRelief = b.place({ key: "relief_valve", tag: "PSV-051", part: "AMPH-RV-001" }, "in", purgeReliefIn, { rotation: 90 });
  b.chain(purgeRelief.vent, "E", { ...PURGE, number: "GN2-153" }, [10, { key: "vent_atmosphere", tag: "VENT-051" }]);

  b.label("HELIUM PRESSURIZATION", at(30, 45), { size: 4 });
  b.label("NITROGEN PURGE", at(30, PURGE_Y - 25), { size: 4 });
  const document = createEmptyDocument({ size: "A1", orientation: "landscape", frame: { kind: "basic", template: "fsdp-standard", columns: 8, rows: 6, margin: 10 } });
  document.items = b.items;
  document.meta.title = "P&ID — Propellant feed and pressurization";
  return {
    number: "TS-0100",
    title: "P&ID\nPROPELLANT FEED AND PRESSURIZATION\nTEST STAND",
    size: "A1",
    system: { name: "Propellant Feed", fluid: "LOX / LCH4" },
    notes: [
      "ALL CRYOGENIC LINES VACUUM JACKETED UNLESS NOTED.",
      "RELIEF DEVICES SET AT VESSEL MAWP; DISCHARGE TO SAFE LOCATION.",
      "PURGE FEED LINES WITH GN2 BEFORE AND AFTER EACH TEST."
    ],
    lineClasses: [
      { name: "HP-316", description: "High pressure gas tubing", material: "316L", rating: "414 bar", wall: "0.065 in", sizes: ['1/4"', '3/8"', '1/2"'] },
      { name: "MP-316", description: "Regulated gas tubing", material: "316L", rating: "100 bar", wall: "0.049 in", sizes: ['1/4"', '1/2"', '1"'] },
      { name: "CRYO-304L", description: "Cryogenic pipe, vacuum jacketed", material: "304L", rating: "50 bar", wall: "SCH 10S", sizes: ['1"', '2"'] }
    ],
    parts: b.parts,
    document
  };
}
